package main

import "fmt"

func main() {
	ch := make(chan int)
	go func() {
		ch <- 6
	}()
	fmt.Println(<-ch)
}

package main

import (
	"fmt"
	"sync"
)

func main() {
	var wg sync.WaitGroup
	ch := make(chan int)
	wg.Add(1)
	go func() {
		defer wg.Done()
		fmt.Println(<-ch)
	}()
	ch <- 4
	wg.Wait()
}

